double fn0(List<double> arr, double target) {
  if (arr.isEmpty) return -1.0;

  int low = 0;
  int high = arr.length - 1;
  double result = -1.0;

  while (low <= high) {
    int mid = (low + high) ~/ 2;
    double val = arr[mid];
    if (val >= target) {
      result = val;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }

  return result;
}

List<String> fn0(String stream) {
  List<int> positions = [];
  for (int i = 0; i < stream.length; i++) {
    if (stream[i] == 'N') positions.add(i);
  }

  if (positions.isEmpty) {
    return [stream];
  }

  const List<String> letters = ['A', 'C', 'G', 'T'];
  List<String> results = [];
  List<String> baseChars = stream.split('');

  void rec(int idx) {
    if (idx == positions.length) {
      results.add(baseChars.join());
      return;
    }
    for (final l in letters) {
      baseChars[positions[idx]] = l;
      rec(idx + 1);
    }
  }

  rec(0);
  return results;
}

