int fn0(List<List<int>> matrix, int k, int l) {
  if (l == 0) {
    return 0;
  }

  int modK = k % l;
  if (modK < 0) modK += l;

  int count = 0;
  for (final row in matrix) {
    int sum = 0;
    for (final v in row) {
      sum += v;
    }
    int modSum = sum % l;
    if (modSum < 0) modSum += l;
    if (modSum == modK) count++;
  }

  return count;
}

