String fn0(int x, int y, int x1, int y1, int x2, int y2) {
  int leftBound = x1 < x2 ? x1 : x2;
  int rightBound = x1 > x2 ? x1 : x2;
  int topBound = y1 < y2 ? y1 : y2;
  int bottomBound = y1 > y2 ? y1 : y2;

  int dx = 0;
  String horiz = '';
  if (x < leftBound) {
    dx = leftBound - x;
    horiz = 'E';
  } else if (x > rightBound) {
    dx = x - rightBound;
    horiz = 'W';
  }

  int dy = 0;
  String vert = '';
  if (y < topBound) {
    dy = topBound - y;
    vert = 'N';
  } else if (y > bottomBound) {
    dy = y - bottomBound;
    vert = 'S';
  }

  String direction;
  if (dx == 0 && dy == 0) {
    direction = 'IN';
  } else {
    direction = vert + horiz;
  }

  int distance = dx + dy;

  return 'Distance: $distance, Direction: $direction';
}

