Set<int> fn0(List<int> nums, int target, int k) {
  Set<int> result = {};
  int n = nums.length;
  if (n == 0 || k <= 0 || k > n) return result;

  int windowSum = 0;
  for (int i = 0; i < k; i++) {
    windowSum += nums[i];
  }

  if (windowSum <= target) {
    for (int i = 0; i < k; i++) {
      result.add(i);
    }
  }

  for (int start = 1; start <= n - k; start++) {
    windowSum = windowSum - nums[start - 1] + nums[start + k - 1];
    if (windowSum <= target) {
      for (int i = start; i < start + k; i++) {
        result.add(i);
      }
    }
  }

  return result;
}

