List<int> fn0(String hand, String suit) {
  List<int> ranks = [];
  List<String> cards = hand.split(' ');

  for (int i = 0; i < cards.length; i++) {
    String card = cards[i];
    if (card.isEmpty) continue;

    String cardSuit = card[card.length - 1];
    if (cardSuit != suit) continue;

    String rankStr = card.substring(0, card.length - 1);
    int value;
    switch (rankStr) {
      case 'A':
        value = 14;
        break;
      case 'K':
        value = 13;
        break;
      case 'Q':
        value = 12;
        break;
      case 'J':
        value = 11;
        break;
      case 'T':
        value = 10;
        break;
      default:
        value = int.parse(rankStr);
    }
    ranks.add(value);
  }

  ranks.sort();
  return ranks;
}

