List<String> fn0(String log, double factor) {
  if (log.isEmpty) return [];
  List<String> result = [];
  for (String item in log.split(';')) {
    if (item.isEmpty) continue;
    List<String> parts = item.split(' ');
    if (parts.isEmpty) continue;
    double val = double.parse(parts[0]);
    double newVal = val * factor;
    String numStr;
    if (newVal == newVal.truncateToDouble()) {
      numStr = newVal.truncate().toString();
    } else {
      numStr = newVal.toString();
    }
    String rest = parts.length > 1 ? parts.sublist(1).join(' ') : '';
    result.add(rest.isEmpty ? numStr : '$numStr $rest');
  }
  return result;
}

